//! `costmap` and `footprint` against the real nav2_costmap_2d (tests/data/costmap.json,
//! regenerated by tests/oracle/run_oracle.sh costmap).

mod common;

use common::{assert_close, f, load};
use mower_nav_core::costmap::{interpret_value, static_costmap, Costmap2D, OccupancyGrid, RollingWindow, StaticLayerParams};
use mower_nav_core::footprint::{calculate_min_and_max_distances, robot_footprint, FootprintCollisionChecker};
use mower_nav_core::geometry::Transform2D;
use serde_json::Value;

fn grid(v: &Value) -> OccupancyGrid {
    OccupancyGrid {
        width: v["width"].as_u64().unwrap() as u32,
        height: v["height"].as_u64().unwrap() as u32,
        resolution: f(&v["resolution"]),
        origin_x: f(&v["origin_x"]),
        origin_y: f(&v["origin_y"]),
        data: v["data"].as_array().unwrap().iter().map(|x| x.as_i64().unwrap() as i8).collect(),
    }
}

fn cells(v: &Value) -> Vec<u8> {
    v["data"].as_array().unwrap().iter().map(|x| x.as_u64().unwrap() as u8).collect()
}

fn assert_costmap(ours: &Costmap2D, theirs: &Value, what: &str) {
    assert_eq!(ours.size_x() as u64, theirs["size_x"].as_u64().unwrap(), "{what}: size_x");
    assert_eq!(ours.size_y() as u64, theirs["size_y"].as_u64().unwrap(), "{what}: size_y");
    assert_eq!(ours.resolution(), f(&theirs["resolution"]), "{what}: resolution");
    assert_close(ours.origin_x(), f(&theirs["origin_x"]), &format!("{what}: origin_x"));
    assert_close(ours.origin_y(), f(&theirs["origin_y"]), &format!("{what}: origin_y"));
    let expected = cells(theirs);
    let diff = ours.data().iter().zip(&expected).filter(|(a, b)| a != b).count();
    assert_eq!(diff, 0, "{what}: {diff} cells differ");
}

#[test]
fn footprint_matches_costmap_2d_ros() {
    let d = load("costmap.json");
    let fp = robot_footprint(f(&d["footprint"]["radius"]));
    let expected = d["footprint"]["points"].as_array().unwrap();
    assert_eq!(fp.len(), expected.len());
    for (p, e) in fp.iter().zip(expected) {
        assert_close(p.0, f(&e[0]), "footprint x");
        assert_close(p.1, f(&e[1]), "footprint y");
    }
    let (inscribed, circumscribed) = calculate_min_and_max_distances(&fp);
    assert_close(inscribed, f(&d["footprint"]["inscribed"]), "inscribed");
    assert_close(circumscribed, f(&d["footprint"]["circumscribed"]), "circumscribed");
}

#[test]
fn interpret_matches_static_layer() {
    let d = load("costmap.json");
    for (key, track) in [("track_unknown", true), ("no_track_unknown", false)] {
        let p = StaticLayerParams::new(track);
        let table = d["interpret"][key].as_array().unwrap();
        for (v, e) in table.iter().enumerate() {
            assert_eq!(interpret_value(&p, v as u8) as u64, e.as_u64().unwrap(), "{key} {v}");
        }
    }
}

#[test]
fn global_costmap_and_collisions() {
    let d = load("costmap.json");
    let map = static_costmap(&grid(&d["global"]["grid"]), &StaticLayerParams::new(true));
    assert_costmap(&map, &d["global"]["costmap"], "global");
    let fp = robot_footprint(0.5);
    let checker = FootprintCollisionChecker::new(&map);
    for c in d["global_collision"].as_array().unwrap() {
        let cost = checker.footprint_cost_at_pose(f(&c[0]), f(&c[1]), f(&c[2]), &fp);
        assert_eq!(cost, f(&c[3]), "pose {c}");
    }
}

#[test]
fn rolling_local_costmap_and_collisions() {
    let d = load("costmap.json");
    let local = &d["local"];
    let map = static_costmap(&grid(&local["grid"]), &StaticLayerParams::new(false));
    let t = &local["map_from_odom"];
    let map_from_odom = Transform2D::new(f(&t[0]), f(&t[1]), f(&t[2]));
    let mut window = RollingWindow::local_costmap();
    let fp = robot_footprint(0.5);
    for (i, step) in local["steps"].as_array().unwrap().iter().enumerate() {
        window.update(f(&step["robot"][0]), f(&step["robot"][1]), &map, &map_from_odom);
        assert_costmap(window.costmap(), &step["costmap"], &format!("local step {i}"));
        let checker = FootprintCollisionChecker::new(window.costmap());
        for c in step["collision"].as_array().unwrap() {
            let cost = checker.footprint_cost_at_pose(f(&c[0]), f(&c[1]), f(&c[2]), &fp);
            assert_eq!(cost, f(&c[3]), "step {i} pose {c}");
        }
    }
}

#[test]
fn update_origin_matches_costmap_2d() {
    let d = load("costmap.json");
    let init = &d["update_origin"]["initial"];
    let mut c = Costmap2D::new(
        init["size_x"].as_u64().unwrap() as u32,
        init["size_y"].as_u64().unwrap() as u32,
        f(&init["resolution"]),
        f(&init["origin_x"]),
        f(&init["origin_y"]),
        0,
    );
    for (i, v) in cells(init).into_iter().enumerate() {
        c.set_cost(i as u32 % c.size_x(), i as u32 / c.size_x(), v);
    }
    for (i, step) in d["update_origin"]["steps"].as_array().unwrap().iter().enumerate() {
        c.update_origin(f(&step["new_origin"][0]), f(&step["new_origin"][1]));
        assert_costmap(&c, &step["costmap"], &format!("update_origin step {i}"));
    }
}
